# The test suite pins the behaviour (call model, pair rules, allele fingerprints) so that this copy and sexloci cannot drift silently.
"""Long insertions that ship with sexloci, so `sexloci sv-genotype` needs no VCF file for them.

deep_benthic_TE: the two candidate transposon insertions on NC_135176.1 (LG10 in GT3a), 216 bp apart, proposed as sex-determination
candidates in a subset of Deep Benthics. Coordinates and alleles are in the VCF anchor-base convention against Mzebra_GT3_NCBI:
POS is the anchor base, REF is that base, ALT is the anchor base followed by the inserted sequence.

chr7_gsdf_ins: the transposon insertion directly upstream of gsdf (the chr7-ins Y allele of Munby et al. 2021, chr7:18,086,980 in fAstCal1.2), as
junction alleles at BOTH copies of the gsdf unit that GT3a holds (a carrier has one copy per chromosome, so its reads split between the two
reference copies; their counts are summed into one call, see SITE_GROUPS). The element is a ~3.8 kb CACT-initial DNA transposon with a 13 bp exact
terminal inverted repeat (RepeatMasker class DNA/CMC-EnSpm, ends = RepeatModeler families rnd-1_family-458 and -764) that creates a 2 bp duplication
of the target site (TG). The allele keeps only what a short read can use, the two junctions: the anchor base (the G ending the first TG), the first 300 and the
last 300 bases of the element, and the duplicated TG. No one has assembled this insertion in full: the element sequence is a modal-length (~3.9 kb) GT3a
copy of the two end families, corrected at the ~500 bp ends with the 9 substitutions and 2 indels that the carriers' read mates showed against it
(template_check_with_mates.py; its default is Munby's 16 carriers). The carriers differ from every one of 25 modal GT3a copies by 14-16 bases per kb, so
no GT3a copy is its source. The alleles were validated against Munby's genotypes for 47 fish: all 16 of his carriers show the junction, none of his
24 non-carriers does, and no sample outside A. calliptera in the database carries it. See docs/VARIANTS.md.

The sequences below were typed in from the lab's insertion VCF. `sexloci sv-genotype` logs the length and an MD5 checksum of each ALT, and
`sexloci write-builtin-vcf` writes them as a VCF; compare either with the original file to confirm they are identical (see fingerprint()).
"""
import hashlib
from typing import Dict, List, Optional

# (chrom, pos, id, ref, alt, info)
_TE1_ALT = (
    ""
)

_TE2_ALT = (
    ""
)

_CHR7INS_ALT = (
    "GCACTCAGAAAAATAAAGGTGCCAACTGGAACCAAAAGTGGTTCTTTAGACTGATGCCATAGAAGAACCTTTTTTGGTGCCACAAAGAAC"
    "CTTTCAAACAATGGTTCTTTGAAGAACCATTTCTTTCAGTGGTTCATTGAAGAACCTTTAAAGGTGCCCCAAAGAACCATCAAGAAATGG"
    "TTCTTTGGGGAACCTTTAATGGTTTTTCAAAGAACCTTTTTAAAAATGGTTCTTTAAAGAACCTTTTTAAAGAACCTTTTTTGAGTGGTT"
    "CTTTAAAAAACCATTTTAAATCTTTCAAAATCTACCATCTTCTCTTAAATGGTAATTGCCAGGTATCCTGCCCTTCCCCTTCGCACACAC"
    "ATGCACACAAAGAAAACACACAGTATAATTCACAGCCTCATTATAGTGAATAAATATTTATGCCATTTACACCATCAAACTTAGATTGCT"
    "AAGGATGAAGAACCTTTTGTTCTTTAAAGAACCATTTGTAATAGCTGAAGAACCATCCACAAAATAAAAAGGTTCTTTGACGTATGATGG"
    "TTCTTTAAAGAACCATGAAGACATCTGAAGAACCATTTAAGAACCATAATTTTTCTGAGTGTG"
)

BUILTIN: Dict[str, List[tuple]] = {
    "deep_benthic_TE": [
        ("NC_135176.1", 24921178, "TE1", "t", _TE1_ALT, "TYPE=INSERTION,ALN_START=197394"),
        ("NC_135176.1", 24921394, "TE2", "a", _TE2_ALT, "TYPE=INSERTION,ALN_START=198749"),
    ],
    "chr7_gsdf_ins": [
        ("NC_135173.1", 50765050, "chr7ins_c1", "G", _CHR7INS_ALT, "TYPE=INSERTION"),
        ("NC_135173.1", 50786787, "chr7ins_c2", "G", _CHR7INS_ALT, "TYPE=INSERTION"),
    ],
}
DEFAULT_SET = "deep_benthic_TE"


# Sites that are one locus seen at several places in the reference. sv-genotype genotypes each member and also writes ONE combined call per sample from
# the summed counts of informative pairs: {combined column name: member site names}. The combined call is used only when all members are being genotyped.
SITE_GROUPS: Dict[str, tuple] = {"chr7ins": ("chr7ins_c1", "chr7ins_c2")}

SITE_GROUP_NOTES: Dict[str, str] = {
    "chr7ins": ("Genotype of the ~3.8 kb transposon insertion directly upstream of gsdf (the chr7-ins Y allele of Munby et al. 2021) from short reads. "
                "Read pairs crossing either junction, at both GT3a copies of the gsdf unit (NC_135173.1:50,765,050 and :50,786,787), are summed "
                "(0/0 absent, 0/1 heterozygous, 1/1 homozygous). In a fish with three or four gsdf copies the insertion allele is a smaller share of the "
                "reads than the model's one half, so a low-fraction heterozygote there can be called 0/0."),
}


def fingerprint(alt: str) -> str:
    """'<length> bp, md5 <first 12 hex>' of the upper-case ALT string: the same number from the original VCF means the same sequence."""
    a = alt.upper()
    return f"ALT {len(a):,} bp, md5 {hashlib.md5(a.encode()).hexdigest()[:12]}"


def builtin_vcf_text(name: str = DEFAULT_SET) -> str:
    """The set as VCF text with real tab characters (same layout as the lab's file: no header, QUAL 100, FILTER *, trailing 'Special')."""
    if name == "all":
        return "".join(builtin_vcf_text(n) for n in BUILTIN)
    if name not in BUILTIN:
        raise KeyError(f"unknown built-in site set {name!r}; available: all, {', '.join(BUILTIN)}")
    return "".join("\t".join([c, str(p), i, r, a, "100", "*", f'"{info}"', "Special"]) + "\n" for c, p, i, r, a, info in BUILTIN[name])


def write_builtin_vcf(path: str, name: str = DEFAULT_SET) -> None:
    with open(path, "w", newline="") as fh:
        fh.write(builtin_vcf_text(name))
